5: import { getBearerToken } from '@/lib/api';
6: 
7: const spring = { type: 'spring' as const, stiffness: 400, damping: 30 };
8: 
9: 
10: /**
11:  * Centre, edge, thinking, listening edge, speaking edge. The beam renders in mono so the composer
12:  * stays black and white in either theme.
13:  */
14: 
15: interface Props {
16:   onSend: (text: string) => void;
17:   onStop: () => void;
18:   streaming: boolean;
19:   /** True once the assistant has emitted at least one token, which separates thinking from speaking. */
20:   hasReplyTokens?: boolean;
21:   disabled?: boolean;
22:   seed?: string;
23:   onSeedConsumed?: () => void;
24: }
25: 
26: export function InputPill({
27:   onSend,
28:   onStop,
29:   streaming,
30:   hasReplyTokens = false,
31:   disabled = false,
32:   seed,
33:   onSeedConsumed,
34: }: Props) {
35:   const [draft, setDraft] = useState('');
36:   const [files, setFiles] = useState<string[]>([]);
37:   const [recording, setRecording] = useState(false);
38:   const [notice, setNotice] = useState<string | null>(null);
39:   const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);
40: 
41:   const areaRef = useRef<HTMLTextAreaElement>(null);
42:   const fileRef = useRef<HTMLInputElement>(null);
43:   const streamRef = useRef<MediaStream | null>(null);
44:   const ctxRef = useRef<AudioContext | null>(null);
45:   const mediaRecorderRef = useRef<MediaRecorder | null>(null);
46:   const chunksRef = useRef<Blob[]>([]);
47: 
48:   useEffect(() => {
49:     if (!seed) return;
50:     setDraft(seed);
51:     onSeedConsumed?.();
52:     areaRef.current?.focus();
53:   }, [seed, onSeedConsumed]);
54: 
55:   // Auto-expand the textarea up to a comfortable ceiling.
56:   useEffect(() => {
57:     const el = areaRef.current;
58:     if (!el) return;
59:     el.style.height = '0px';
60:     el.style.height = `${Math.min(el.scrollHeight, 160)}px`;
61:   }, [draft]);
62: 
63:   // Microphone hardware must never outlive the component.
64:   useEffect(() => {
65:     return () => {
66:       if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
67:         try {
68:           mediaRecorderRef.current.stop();
69:         } catch {
70:           // cleanup
71:         }
72:       }
73:       streamRef.current?.getTracks().forEach((track) => track.stop());
74:       void ctxRef.current?.close();
75:     };
76:   }, []);
77: 
78:   const releaseCapture = () => {
79:     streamRef.current?.getTracks().forEach((track) => track.stop());
80:     streamRef.current = null;
81:     void ctxRef.current?.close();
82:     ctxRef.current = null;
83:     setAnalyser(null);
84:   };
85: 
86:   const transcribeAudio = async (audioBlob: Blob) => {
87:     try {
88:       setNotice('Transcribing audio...');
89:       const formData = new FormData();
90:       formData.append('file', audioBlob, 'recording.webm');
91: 
92:       const headers: Record<string, string> = {};
93:       const token = getBearerToken();
94:       if (token) {
95:         headers['Authorization'] = `Bearer ${token}`;
96:       }
97: 
98:       const res = await fetch('/api/v1/voice/transcribe', {
99:         method: 'POST',
100:         headers,
101:         body: formData,
102:       });
103: 
104:       if (!res.ok) {
105:         throw new Error(`Transcription failed (${res.status})`);
106:       }
107: 
108:       const data = (await res.json()) as { text?: string };
109:       const transcribedText = data?.text?.trim();
110:       if (transcribedText) {
111:         setDraft((prev) => (prev ? `${prev.trim()} ${transcribedText}` : transcribedText));
112:         setNotice(null);
113:         areaRef.current?.focus();
114:       } else {
115:         setNotice('No speech recognized.');
116:       }
117: 
118:     } catch {
119:       setNotice('Voice transcription failed. You can type your message instead.');
120:     }
121:   };
122: 
123:   const startCapture = async () => {
124:     if (!navigator.mediaDevices?.getUserMedia) {
125:       setNotice('This browser exposes no microphone to the page.');
126:       return;
127:     }
128:     try {
129:       const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
130:       streamRef.current = stream;
131: 
132:       const ctx = new AudioContext();
133:       ctxRef.current = ctx;
134:       const source = ctx.createMediaStreamSource(stream);
135:       const node = ctx.createAnalyser();
136:       node.fftSize = 1024;
137:       node.smoothingTimeConstant = 0.65;
138:       source.connect(node);
139: 
140:       setAnalyser(node);
141: 
142:       chunksRef.current = [];
143:       if (typeof MediaRecorder !== 'undefined') {
144:         const recorder = new MediaRecorder(stream);
145:         recorder.ondataavailable = (event) => {
146:           if (event.data && event.data.size > 0) {
147:             chunksRef.current.push(event.data);
148:           }
149:         };
150:         recorder.start(100);
151:         mediaRecorderRef.current = recorder;
152:       }
153: 
154:       setRecording(true);
155:       setNotice(null);
156:     } catch {
157:       setNotice('Microphone permission was declined, so nothing is being captured.');
158:     }
159:   };
160: 
161:   const stopCapture = () => {
162:     setRecording(false);
163:     const recorder = mediaRecorderRef.current;
164:     if (recorder && recorder.state !== 'inactive') {
165:       recorder.onstop = () => {
166:         const chunks = chunksRef.current;
167:         if (chunks.length > 0) {
168:           const audioBlob = new Blob(chunks, { type: 'audio/webm' });
169:           void transcribeAudio(audioBlob);
170:         }
171:       };
172:       try {
173:         recorder.stop();
174:       } catch {
175:         // Fallback
176:       }
177:     }
178:     mediaRecorderRef.current = null;
179:     releaseCapture();
180:   };
181: 
182: 
183:   const toggleRecording = () => {
184:     if (recording) {
185:       stopCapture();
186:       return;
187:     }
188:     setNotice(null);
189:     void startCapture();
190:   };
191: 
192:   const canSend = (draft.trim().length > 0 || files.length > 0) && !streaming && !disabled;
193: 
194:   const submit = () => {
195:     if (!canSend) return;
196:     onSend(draft);
197:     setDraft('');
198:     setFiles([]);
199:     setNotice(null);
200:   };
201: 
202:   const phase: BeamPhase = recording
203:     ? 'listening'
204:     : streaming
205:       ? hasReplyTokens
206:         ? 'speaking'
207:         : 'thinking'
208:       : 'idle';
209: 
210:   return (
211:     <div className="pointer-events-none fixed inset-x-0 bottom-28 z-30 flex justify-center px-4 md:bottom-10 md:pl-20">
212:       <div className="pointer-events-auto w-full max-w-2xl">
213:         <AnimatePresence>
214:           {files.length > 0 && (
215:             <motion.div
216:               initial={{ opacity: 0, y: 8 }}
217:               animate={{ opacity: 1, y: 0 }}
218:               exit={{ opacity: 0, y: 8 }}
219:               transition={spring}
220:               className="mb-2 flex flex-wrap gap-2 px-2"
221:             >
222:               {files.map((f) => (
223:                 <span
224:                   key={f}
225:                   className="glass inline-flex items-center gap-1.5 rounded-[8px] py-1 pl-3 pr-1.5 text-xs text-[var(--text-muted)]"
226:                 >
227:                   <Paperclip size={12} strokeWidth={1.5} />
228:                   {f}
229:                   <button
230:                     type="button"
231:                     aria-label={`Remove ${f}`}
232:                     onClick={() => setFiles((fs) => fs.filter((x) => x !== f))}
233:                     className="flex h-5 w-5 items-center justify-center rounded-[5px] hover:bg-[color-mix(in_srgb,var(--text)_10%,transparent)]"
234:                   >
235:                     <X size={12} strokeWidth={1.5} />
236:                   </button>
237:                 </span>
238:               ))}
239:             </motion.div>
240:           )}
241:         </AnimatePresence>
242: 
243:         {notice ? (
244:           <p role="status" className="mb-2 px-3 text-[12px] text-[var(--text-muted)]">
245:             {notice}
246:           </p>
247:         ) : null}
248: 
249:         <HandoffBeam
250:           phase={phase}
251:           analyser={recording ? analyser : null}
252:           palette="mono"
253:           radius={16}
254:           className="glass"
255:           phaseLabels={{
256:             idle: 'Ready',
257:             listening: 'Listening',
258:             thinking: 'Vigil is thinking',
259:             speaking: 'Vigil is replying',
260:           }}
261:         >
262:           <div className="flex items-end gap-2 p-2">
263:             <input
264:               ref={fileRef}
265:               type="file"
266:               multiple
267:               hidden
268:               onChange={(e) => {
269:                 const names = Array.from(e.target.files ?? []).map((f) => f.name);
270:                 setFiles((fs) => [...fs, ...names]);
271:                 e.target.value = '';
272:               }}
273:             />
274:             <button
275:               type="button"
276:               aria-label="Attach a file"
277:               onClick={() => fileRef.current?.click()}
278:               disabled={disabled}
279:               className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-[color-mix(in_srgb,var(--text)_8%,transparent)] text-[var(--text-muted)] transition-transform duration-300 ease-spring hover:scale-105 hover:text-[var(--text)] active:scale-95 disabled:opacity-40"
280:             >
281:               <Plus size={18} strokeWidth={1.5} />
282:             </button>
283: 
284:             <div className="flex min-h-11 flex-1 items-center">
285:               {recording ? (
286:                 <div className="flex items-center gap-3 px-2 text-sm text-[var(--text-muted)]">
287:                   <span className="relative flex h-2 w-2">
288:                     <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-[var(--text)] opacity-60" />
289:                     <span className="relative inline-flex h-2 w-2 rounded-full bg-[var(--text)]" />
290:                   </span>
291:                   Listening...
292:                 </div>
293:               ) : (
294:                 <label htmlFor="vigil-composer" className="sr-only">
295:                   Message Vigil
296:                 </label>
297:               )}
298:               {recording ? null : (
299:                 <textarea
300:                   id="vigil-composer"
301:                   ref={areaRef}
302:                   rows={1}
303:                   value={draft}
304:                   onChange={(e) => setDraft(e.target.value)}
305:                   onKeyDown={(e) => {
306:                     if (e.key === 'Enter' && !e.shiftKey) {
307:                       e.preventDefault();
308:                       submit();
309:                     }
310:                   }}
311:                   placeholder="Ask Vigil anything or assign a task..."
312:                   disabled={disabled}
313:                   className="max-h-[160px] w-full resize-none rounded-[12px] bg-[color-mix(in_srgb,var(--text)_10%,transparent)] px-3 py-[10px] text-[15px] leading-relaxed text-[var(--text)] outline-none placeholder:text-[var(--text-muted)] disabled:opacity-60"
314:                 />
315:               )}
316:             </div>
317: 
318:             <button
319:               type="button"
320:               aria-label={recording ? 'Stop recording' : 'Record voice'}
321:               aria-pressed={recording}
322:               onClick={toggleRecording}
323:               disabled={disabled}
324:               className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-[var(--text-muted)] transition-transform duration-300 ease-spring hover:scale-105 hover:text-[var(--text)] active:scale-95 disabled:opacity-40"
325:               style={
326:                 recording
327:                   ? {
328:                       color: 'var(--text)',
329:                       background: 'color-mix(in srgb, var(--text) 14%, transparent)',
330:                     }
331:                   : undefined
332:               }
333:             >
334:               <Mic size={18} strokeWidth={1.5} />
335:             </button>
336: 
337:             <button
338:               type="button"
339:               aria-label={streaming ? 'Stop generating' : 'Send'}
340:               disabled={!streaming && !canSend}
341:               onClick={streaming ? onStop : submit}
342:               className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full transition-all duration-300 ease-spring active:scale-95"
343:               style={
344:                 streaming || canSend
345:                   ? {
346:                       background: 'var(--accent)',
347:                       color: 'var(--accent-ink)',
348:                     }
349:                   : {
350:                       background: 'color-mix(in srgb, var(--text) 8%, transparent)',
351:                       color: 'var(--text-muted)',
352:                     }
353:               }
354:             >
355:               {streaming ? (
356:                 <Square size={15} strokeWidth={2} />
357:               ) : (
358:                 <ArrowUp size={18} strokeWidth={1.75} />
359:               )}
360:             </button>
361:           </div>
362:         </HandoffBeam>
363:       </div>
364:     </div>
365:   );
366: }
367: 
368: export default InputPill;
